import React, { createContext, useContext, useMemo } from 'react';

type AppliedFilterContextType = {
  viewOnly?: boolean;
  disabledFilterMessage: string;
};
const initialValue: AppliedFilterContextType = {
  viewOnly: false,
  disabledFilterMessage: 'This filter can only be changed outside the player. Please navigate back to adjust.',
};
const AppliedFilterContext = createContext<AppliedFilterContextType>(initialValue);

type AppliedFilterContextProviderProps = {
  children: React.ReactNode;
  viewOnly?: boolean;
};

export const AppliedFilterContextProvider = ({ children, viewOnly = false }: AppliedFilterContextProviderProps) => {
  const value = useMemo(() => ({ ...initialValue ,viewOnly, disabledFilterMessage : viewOnly ? initialValue.disabledFilterMessage : '' }), [viewOnly]);
  
  return (
    <AppliedFilterContext.Provider value={value}>
      {children}
    </AppliedFilterContext.Provider>
  );
};

export const useAppliedFilterContext = () => {
  const context = useContext(AppliedFilterContext);
  if (context === undefined) {
    throw new Error('useAppliedFilterContext must be used within a AppliedFilterContextProvider');
  }
  return context;
}; 