import React from 'react'
import styled from 'styled-components'

const HighlightSpan = styled.span`
  color: #5D97FF !important;
  font-weight: 600;
  padding: 0 1px;
`

/**
 * Highlights matching text within a string
 * @param {string|React.ReactNode} text - The text to search within (can be string or React element)
 * @param {string} searchTerm - The term to highlight
 * @returns {React.ReactNode} - Text with highlighted matches
 */
export const highlightText = (text, searchTerm) => {
  // If text is not a string or searchTerm is empty, return as is
  if (!searchTerm || typeof text !== 'string') {
    return text
  }

  const trimmedSearch = searchTerm.trim()
  if (!trimmedSearch) {
    return text
  }

  try {
    // Escape special regex characters in search term
    const escapedSearch = trimmedSearch.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    const regex = new RegExp(`(${escapedSearch})`, 'gi')

    const parts = text.split(regex)

    return (
      <>
        {parts.map((part, index) => {
          const isMatch = part.toLowerCase() === trimmedSearch.toLowerCase()
          return isMatch ? (
            <HighlightSpan key={index}>{part}</HighlightSpan>
          ) : (
            <React.Fragment key={index}>{part}</React.Fragment>
          )
        })}
      </>
    )
  } catch (error) {
    // If regex fails, return original text
    return text
  }
}

/**
 * Higher-order component that wraps text content with highlighting capability
 * @param {React.ReactNode} content - Content that may contain text to highlight
 * @param {string} searchTerm - The term to highlight
 * @returns {React.ReactNode} - Content with highlighted text
 */
export const withHighlight = (content, searchTerm) => {
  if (React.isValidElement(content)) {
    // If content is already a React element, try to extract and highlight its text
    if (typeof content.props.children === 'string') {
      return React.cloneElement(content, {
        children: highlightText(content.props.children, searchTerm)
      })
    }
    return content
  }

  if (typeof content === 'string') {
    return highlightText(content, searchTerm)
  }

  return content
}
