import moment from 'moment/moment';

export const removeMilliseconds = (value, type, keepTime = true) => {
  if(keepTime) return `${moment.utc(value).toISOString().split('.')[0]}Z`
  if(type === 'start') return `${moment.utc(value).startOf('day').toISOString().split('.')[0]}Z`
  return `${moment.utc(value).endOf('day').toISOString().split('.')[0]}Z`
}

export const disabledDate = (current) => current && current > moment().endOf('day');
