/* eslint-disable react/jsx-props-no-spreading */
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { fetchPlanHatApi } from 'redux/actions/common';
import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';
import { Button, Checkbox, Tooltip, Select } from 'antd';
import { mapPageNames } from 'Utils/constants/index';
import { useChangeColumn } from 'components/features/sessions/hooks/useSessionItems';
import {
  getItemStyle,
  getListStyle,
  getTableType,
  reorder,
} from 'Utils/helpers/SessionUtils';

import { CloseOutlined, SearchOutlined } from '@ant-design/icons';


import uniq from 'lodash/uniq';
import filter from 'lodash/filter';
import includes from 'lodash/includes';

import { trackPageViews } from 'redux/actions/trackingReport';
import difference from 'lodash/difference';
import styled from 'styled-components';
import { bringSelectedItemsToTop } from 'components/shared/GlobalFilter/components/CommonComponentsV2';
import { useIsAppType } from 'hooks/useIsAppType';
import { keyLabelMap } from 'components/shared/GlobalFilter/components/utils';
import useCustomPropModal from '../../shared/CustomPropertyModal';

import { MenuOutlinedWrapper, CustomPropButton, ActionButtonsWrapper, RemoveButton, SearchInput, ButtonWrapper, InputContainer, NotFoundText, ColumnWrapper } from './styles';

import { useCustomPropsUtils, generateLocalHeadersData } from './utils';

const ColumnWrapperInner = styled.div`
  overflow: auto;
  overflow-x: hidden;
`

const COLUMN_UPDATE_URL = 'preference/column-update';
const attributeMap = ['event_name', 'name', 'lastseen', 'sessionhashofuser', 'relevance_score'];

const ColumnUpdate = ({
  type,  // type can be user, event, nocodeEvent, session, or aiSession
  saveLocally = false,
  setLocalHeaders = () => {},
  closeLocal = () => {},
  appid,
  setLoading,
  setDropdownVisibility,
  headers:rawHeaders,
  dropdownVisible,
  showAddCustomUserButton,
  showAddCustomEventButton,
  minWidth = 250,
  onResetSuccess,
}) => {
  const dispatch = useDispatch();
  const { mutate, isLoading, status } = useChangeColumn();
  const isWebApp = useIsAppType( 'web' );
  const { parentType } = useSelector(state => state.urlReducer)
  const modifiedHeaders = useCallback(() => {
    return rawHeaders?.map(header => {
        return {
          ...header,
          title: keyLabelMap[header.title] || header.title, 
        };
      }
    );
  },[rawHeaders])
  const [tableHeader, setTableHeader] = useState(modifiedHeaders);
  const [eventTriggered, setEventTriggered] = useState({
    checkedEvent: false,
    dragEvent: false,
  });

  const { openModal, setOpenModal, CustomPropertyModal } = useCustomPropModal();
  const [modalSelected, setModalSelected] = useState('');

  const [selectedCustomProps, setSelectedCustomProps] = useState([]);
  const [selectedCustomEventProps, setSelectedCustomEventProps] = useState([]);
  const [selectedCustomUserProps, setSelectedCustomUserProps] = useState([]);
  const [removedCustomProps, setRemovedCustomProps] = useState([]);
  const {
    customPropertiesSelectOptions,
    filterOutUnslectedCustom,
    filteredOutPositionArray,
    customPropsPresentInHeader,
    getColumnUpdateObject,
    existingCustomEventProps,
    existingCustomUserProps,
    stripCustomPropertyAndMapLabel,
  } = useCustomPropsUtils({
    headers: tableHeader || [],
    modalType: modalSelected,
    selectedCustomProps: modalSelected === 'user' ? selectedCustomUserProps : selectedCustomEventProps,
    overallSelectedCustomProps: [...selectedCustomUserProps, ...selectedCustomEventProps],
    excludeEventProps: parentType !== 'eventsList',
  });

  const [dropdownOpen, setDropdownOpen] = useState(false);
  const [customPropSearch, setCustomPropSearch] = useState('');
  const [lastAddedColumn, setLastAddedColumn] = useState(null);

  const filteredCustomSelectOptions = useMemo(() => filter(bringSelectedItemsToTop(customPropertiesSelectOptions, modalSelected === 'user' ? selectedCustomUserProps : selectedCustomEventProps), val => {
    if (customPropSearch.length === 0) {
      return true;
    }
    return includes(stripCustomPropertyAndMapLabel(val).toLowerCase(), customPropSearch.toLowerCase());
  }), [customPropSearch, customPropertiesSelectOptions, modalSelected, stripCustomPropertyAndMapLabel])

  const isColumnDisabled = (column) => attributeMap.includes(column?.attribute);

  // Helper function to update custom property arrays
  const updateCustomPropertyState = useCallback((
    selectedColumn,
    isCheckedColumn,
    propertyType,
    currentArray,
    setterFunction
  ) => {
    if (!isCheckedColumn) {
      const newArray = filter(currentArray, val => val !== selectedColumn);
      setterFunction(newArray);

      if (modalSelected === propertyType) {
        setSelectedCustomProps(newArray);
      }
    } else if (!currentArray.includes(selectedColumn)) {
      const newArray = [...currentArray, selectedColumn];
      setterFunction(newArray);

      if (modalSelected === propertyType) {
        setSelectedCustomProps(newArray);
      }
    }
  }, [modalSelected]);

const handleChange = useCallback(async (e) => {
  setEventTriggered({ ...eventTriggered, checkedEvent: true });
  const selectedColumn = e.target.value;
  const isCheckedColumn = e.target.checked;
  const objIndex = tableHeader.findIndex(
    (item) => item.attribute === selectedColumn
  );

  // Update the visibility in tableHeader
  tableHeader[objIndex].isVisible = isCheckedColumn;
  setTableHeader([...tableHeader]);

  // Handle custom property state updates
  const columnObj = tableHeader[objIndex];

  if (columnObj.isCustomUserProperty) {
    updateCustomPropertyState(
      selectedColumn,
      isCheckedColumn,
      'user',
      selectedCustomUserProps,
      setSelectedCustomUserProps
    );
  } else if (columnObj.isCustomEventProperty) {
    updateCustomPropertyState(
      selectedColumn,
      isCheckedColumn,
      'event',
      selectedCustomEventProps,
      setSelectedCustomEventProps
    );
  }

  if (isCheckedColumn) {
    setLastAddedColumn(selectedColumn);
  }
}, [tableHeader, eventTriggered, selectedCustomUserProps, selectedCustomEventProps, updateCustomPropertyState]);
  const calculateColumnPosition = (sourceIndex, destinationIndex) => {
    const newData = reorder(tableHeader, sourceIndex, destinationIndex)
    setTableHeader( newData )
  };

  const onDragEnd = (result) => {
    const destination = tableHeader[result?.destination?.index];
    if (!result.destination || isColumnDisabled(destination)) {
      return;
    }
    setEventTriggered({ ...eventTriggered, dragEvent: true });
    if (destination.isDraggable) {
      calculateColumnPosition(result.source.index, result.destination.index);
    }
  };

  const handleResetBtn = useCallback(() => {
    const data = {
      appid,
      table: getTableType(type),
      is_reset: true,
    };
    if ( saveLocally ) {
      let defaultLocalAIHeaders = ''
      try {
        defaultLocalAIHeaders = sessionStorage.getItem( 'aiDefaultHeaders' )
      } catch (err) {
        // silent fail
      }
      if ( defaultLocalAIHeaders ) {
        const newData = JSON.parse( defaultLocalAIHeaders ) 
        setTableHeader( newData )
        setLocalHeaders( newData )
        setSelectedCustomUserProps( [])
        try {
          sessionStorage.setItem( 'aiHeaders', defaultLocalAIHeaders )
        } catch (err) {
          // silent fail
        }
      }
      closeLocal()
    } else {
      mutate({ data, url: COLUMN_UPDATE_URL, type }, {
        onSuccess: () => {
          onResetSuccess?.();
        },
      });
    }
  }, [ appid, saveLocally, mutate, type, isWebApp, closeLocal, setLocalHeaders, onResetSuccess ]);

  const handleDoneBtn = useCallback(async (update) => {
    const visibleArray = [];
    const positionArray = [];

    await eventTriggered.checkedEvent &&
      filter(filterOutUnslectedCustom, (item) => {
        visibleArray.push(getColumnUpdateObject(item))
      }    
      );
    
    filter(filteredOutPositionArray, (item) => positionArray.push(item.attribute));

    const data = {
      appid,
      visibility: eventTriggered.checkedEvent ? visibleArray : filterOutUnslectedCustom.map(v => getColumnUpdateObject(v)),
      position: uniq(positionArray),
      table: getTableType(type),
    };
    
    if (lastAddedColumn) {
      dispatch(trackPageViews(null, {
        eventName: 'wa_column_add',
        track_type: 'event',
        eventProperty: {
          column_name: lastAddedColumn,
        }
      }));
    }
    if ( saveLocally ) {
      const newHeadersData = generateLocalHeadersData( tableHeader, data )
      setLocalHeaders( newHeadersData )
      setTableHeader( newHeadersData )
      try {
        sessionStorage.setItem( 'aiHeaders', JSON.stringify( newHeadersData ) )
      } catch (err) {
        // silent fail
      }
      setOpenModal( false )
      closeLocal()
    } else {
      mutate({ data, url: COLUMN_UPDATE_URL, type }, {
        onError: (error) => {
          console.error(error)
        }
      });
    }
    dispatch(
      fetchPlanHatApi({ action: `Changed column setup on ${mapPageNames[parentType]} page` })
    );

    if(typeof update === 'boolean' && update){
      dispatch(trackPageViews(null, {
        eventName: modalSelected === 'user' ? 'wa_custom_user_property' : 'wa_custom_event_property',
        track_type: 'event',
        eventProperty: {
          property_added: modalSelected === 'user' ? selectedCustomUserProps : selectedCustomEventProps,
          property_removed: difference(removedCustomProps, selectedCustomProps),
        },
      }));
    }

  }, [tableHeader, lastAddedColumn, eventTriggered?.checkedEvent, selectedCustomEventProps, selectedCustomUserProps, filteredOutPositionArray, generateLocalHeadersData, setLocalHeaders, closeLocal]);

  const handleCancelBtn = () => setDropdownVisibility(false);

  useEffect(() => {
    setLoading(isLoading);
  }, [isLoading]);

  useEffect(() => {
    if (dropdownVisible) {
      setSelectedCustomEventProps(existingCustomEventProps);
      setSelectedCustomUserProps(existingCustomUserProps);
    }
    else {
      setTableHeader(modifiedHeaders);
    }
  }, [dropdownVisible])

  useEffect(() => {
    if(modalSelected === 'user') {
      setSelectedCustomProps(selectedCustomUserProps);
    } else {
      setSelectedCustomProps(selectedCustomEventProps);
    }
  }, [modalSelected, selectedCustomUserProps, selectedCustomEventProps])

  useEffect(() => {
    if(status === 'success') {
      setTableHeader(modifiedHeaders);
      setDropdownVisibility(false);
      openModal && setOpenModal(false);
    };
  }, [status]);

  const initialRef = useRef( false )
  useEffect( () => {
    if ( saveLocally && !initialRef.current && JSON.stringify( rawHeaders ) !== JSON.stringify( tableHeader ) ) {
      setTableHeader( rawHeaders)
      initialRef.current = true;
    }
  }, [ rawHeaders, tableHeader, saveLocally ] )

  const getModalTitle = useCallback(() => {
    switch(modalSelected) {
      case 'event':
        return 'event';
      case 'user':
        return 'user';
      default:
        return 'user';
    }
  }, [modalSelected])

  const handleSelectChange = (value) => {
    modalSelected === 'event' ? setSelectedCustomEventProps(value) : setSelectedCustomUserProps(value);
    setRemovedCustomProps(selectedCustomProps);
    setSelectedCustomProps(value);
  }

  const handleRemoveCustomUserProps = useCallback((item) => {
    const newHeader = filter(tableHeader, header => !includes(header.attribute, item.attribute));
    const newSelectedCustomUserProps = filter(existingCustomUserProps, val => !includes(val, item.attribute));
    const newSelectedCustomEventProps = filter(existingCustomEventProps, val => !includes(val, item.attribute));

    if ( saveLocally ) {
      setLocalHeaders( newHeader )
      try {
        sessionStorage.setItem( 'aiHeaders', JSON.stringify( newHeader ) )
      } catch (err) {
        // silent fail
      }
    }
    
    setTableHeader( newHeader )
    if (item.isCustomEventProperty) {
        setSelectedCustomEventProps(newSelectedCustomEventProps);
    } else if (item.isCustomUserProperty) {
        setSelectedCustomUserProps(newSelectedCustomUserProps);
    }
  }, [tableHeader, existingCustomUserProps, existingCustomEventProps]);
  
    const dropDownRenderComponent = useCallback((menu) => (
        <>
            <InputContainer onKeyDown={e => {
                if (e.keyCode === 8) {
                    e.stopPropagation();
                }
            }}>
                <SearchOutlined />
                <SearchInput
                    placeholder='Search'
                    debounceTimeout={500}
                    minLength={1}
                    value={customPropSearch}
                    onChange={e => {
                        setCustomPropSearch(e.target.value);
                    }}
                />
            </InputContainer>
            {menu}
        </>
    ), [customPropSearch]);

  return (
    <>
    <CustomPropertyModal 
      title={`Choose custom ${getModalTitle()} properties`}
      subtitle="You can add a maximum of 3 properties"
      handleOk={() => {
        handleDoneBtn(true)
      }}
      handleCancel={() => {
        setCustomPropSearch('');
        const openedCustomProps = modalSelected === 'user' ? existingCustomUserProps : existingCustomEventProps;
        setSelectedCustomProps(openedCustomProps);
      }}
      disabled={selectedCustomProps.length > 3}
    >
      <Select 
        placeholder={`Select custom ${modalSelected} properties`}
        dropdownRender={dropDownRenderComponent}
        onInputKeyDown={e => {
            // Prevents backspace from triggering select clear
            if (e.keyCode === 8) {
                e.stopPropagation();
            }
        }}
        notFoundContent={<NotFoundText>No matching filter</NotFoundText>}
        showArrow
        showSearch={false}
        value={modalSelected === 'user' ? selectedCustomUserProps : selectedCustomEventProps}
        open={dropdownOpen}
        onDropdownVisibleChange={visible => setDropdownOpen(visible)}
        mode='multiple'
        getPopupContainer={node => node.parentNode}
        onChange={handleSelectChange}
        optionLabelProp='label'
        menuItemSelectedIcon={null}
      >
        {
          filteredCustomSelectOptions.length && filteredCustomSelectOptions.map(item => (
              <Select.Option key={item} value={item} label={stripCustomPropertyAndMapLabel(item)}
                disabled={
                  selectedCustomProps.length >= 3 ? 
                  !selectedCustomProps.includes(item)
                  : false
                }
              >
                <Checkbox checked={selectedCustomProps.includes(item)} />
                {stripCustomPropertyAndMapLabel(item)}
              </Select.Option>
          ))
        }
      </Select>
    </CustomPropertyModal>
    <ColumnWrapper>
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable droppableId="droppable">
          {(provided, snapshot) => (
            <ColumnWrapperInner className="column-wrapper">
              <div
                ref={provided.innerRef}
                style={getListStyle(snapshot.isDraggingOver, minWidth)}
                className="column-order-menu"
              >
                {tableHeader &&
                  tableHeader.map((obj, index) => (
                    <Draggable
                      key={obj.attribute}
                      draggableId={index}
                      isDragDisabled={isColumnDisabled(obj) || !obj?.isDraggable}
                      disableInteractiveElementBlocking
                      index={index}
                    >
                      {(provided, snapshot) => (
                        <div className="column-reorder-dropdown-row">
                          <div
                            className="column-edit-items"
                            ref={provided.innerRef}
                            style={getItemStyle(
                              provided.draggableProps.style,
                              snapshot.isDraggingOver
                            )}
                            {...provided.dragHandleProps}
                            {...provided.draggableProps}
                          >
                            <Checkbox
                              checked={obj.isVisible}
                              value={obj.attribute}
                              disabled={isColumnDisabled(obj)}
                              onChange={handleChange}
                            >
                              {
                                // check if it is a custom property to display italic
                                obj.isCustomUserProperty || obj.isCustomEventProperty ? (
                                  <Tooltip title={`Custom ${obj.isCustomUserProperty ? 'user' : 'event'} property`}>
                                    <div className='label-wrapper'>
                                      <em>
                                        {obj.title} {obj.subTitle ? obj.subTitle : ''}
                                      </em>
                                    </div>
                                  </Tooltip>
                                ) : 
                                  (`${obj.title} ${obj.subTitle ? obj.subTitle : ''}`)
                              }
                            </Checkbox>

                            <ActionButtonsWrapper>
                              {obj.isDraggable && (
                                <a href="#!" className="movable-handle">
                                  <MenuOutlinedWrapper />
                                </a>
                              )}

                              {/* display remove for custom props */}
                              {
                                obj.isCustomUserProperty || obj.isCustomEventProperty ? (
                                  <RemoveButton onClick={() => {
                                    handleRemoveCustomUserProps(obj)
                                  }}>
                                    <CloseOutlined />
                                  </RemoveButton>
                                ) : null
                              }
                            </ActionButtonsWrapper>
                          </div>
                          {provided.placeholder}
                        </div>
                      )}
                    </Draggable>
                  ))}
                {provided.placeholder}
              </div>
            </ColumnWrapperInner>
          )}
        </Droppable>
      </DragDropContext>

      <div>
      {
        showAddCustomEventButton ? (
          <CustomPropButton onClick={() => {
            setModalSelected('event');
            setSelectedCustomEventProps(customPropsPresentInHeader('event'));
            setOpenModal(true)}}>
            <img src='/static/circle-plus.svg' alt='add-icon'/>
            Add custom event properties
          </CustomPropButton>
        ) : null
      }

      {
        showAddCustomUserButton ? (
          <CustomPropButton onClick={() => {
            setModalSelected('user');
            setSelectedCustomUserProps(customPropsPresentInHeader('user'));
            setOpenModal(true)}}>
            <img src='/static/circle-plus.svg' alt='add-icon'/>
            Add custom user properties
          </CustomPropButton>
        ) : null
      }
     
      <ButtonWrapper data-element="column-reorder-button-wrapper">
        {/* <Button
          type="text"
          className="reset-btn"
          onClick={handleResetBtn}
        >
          Reset to default
        </Button> */}
        <Button
          type="link"
          className="reset-btn"
          onClick={() => {
            handleResetBtn();
            handleCancelBtn();
          }}
        >
          Reset
        </Button>
        <Button
          type="primary"
          className="done-btn"
          onClick={handleDoneBtn}
        >
          Apply
        </Button>
      </ButtonWrapper>
      </div>
    </ColumnWrapper>
    </>
  );
};

export default ColumnUpdate;
