const SelectWithTags = memo(({ placeholder, value, handleChange, maxTagCount = 2, numeric = true, tokenSeparators = [',', ' '] ,disabled=false}) => (
    <Select
      mode='tags'
      placeholder={placeholder}
      className='filter-select-input'
      dropdownClassName='filter-input-dropdown increased-dropdown-zIndex'
      maxTagCount={maxTagCount}
      value={value}
      onSelect={useCallback((v0) => numeric && !onlyNumber.test(v0) && message.error('Only numbers are allowed!'), [ numeric ])}
      onChange={handleChange}
      notFoundContent={null}
      autoFocus
      style={{ minWidth: 170 }}
      tokenSeparators={tokenSeparators}
      disabled={disabled}
    />
))
const DateType = memo(({
  selectedOperator,
  onDateChange,
  defaultValue: value,
  editFieldVisibility,
  fromMegaFilter,
  disabled
}) => {
  let defaultValue = null;
  let valueCopy = value;
  if(isArray(valueCopy)) {
    valueCopy = valueCopy.map(v => moment.utc(v).format('YYYY-MM-DD HH:mm:ss'))
    valueCopy = JSON.parse(JSON.stringify(valueCopy))
    defaultValue = [dateWithTime(valueCopy[0]), dateWithTime(valueCopy[1])]
  }
  if(isObject(valueCopy) && valueCopy['lower']) defaultValue = [date(valueCopy['lower']), date(valueCopy['upper'])]

  return selectedOperator?.attribute === 'between' ? (
    <RangePicker
      format={dateFormatWithTime}
      dropdownClassName='increased-dropdown-zIndex date-picker-zIndex'
      disabledDate={disabledDate || disabled}
      onChange={(_, dateString) => {
        let dateStringCopy = dateString
        dateStringCopy = [...dateString].map((v,i) => removeMilliseconds(v, i === 0 && 'start', !fromMegaFilter))
        onDateChange(dateStringCopy, true)
      }}
      defaultValue={defaultValue}
      defaultOpen={editFieldVisibility}
      placeholder={['From', 'To']}
      clearIcon={false}
      locale={localeMon}
      // showTime
    />
  ) : (
    <DatePicker
      format={dateFormat}
      disabledDate={disabledDate || disabled}
      dropdownClassName='increased-dropdown-zIndex date-picker-zIndex'
      onChange={(_, dateString) => onDateChange(dateString)}
      defaultValue={ !valueCopy || isObject(valueCopy) ? null : date(valueCopy) }
      defaultOpen={editFieldVisibility}
      clearIcon={false}
      locale={localeMon}
    />
    
)})
const DebounceInputComponent = memo(({
    debounceTimeout = 500,
    className,
    autoFocus = true,
    placeholder = 'Input text',
    onPressEnter,
    onChange,
    defaultValue = undefined,
    value = undefined,
    style,
    prefix,
    suffix,
    onClick,
    onBlur,
    onMouseLeave,
    editFieldVisibility,
    min,
    type,
    disabled,
    inputRef
  }) => (
    <>
      {prefix}
      <DebounceInput
        inputRef={inputRef}
        autoFocus={autoFocus}
        debounceTimeout={debounceTimeout}
        className={cs(`ant-input debounce-input ${className}`, {
          'input-with-search': prefix,
          'input-with-cross': editFieldVisibility ||  suffix,
        })}
        placeholder={placeholder}
        onChange={onChange}
        defaultValue={defaultValue}
        value={value}
        style={style}
        onKeyDown={(e) => {
          e.stopPropagation()
          onPressEnter ? e.key === 'Enter' && onPressEnter(e) : null
        }}
        onClick={onClick}
        onBlur={onBlur}
        onMouseLeave={onMouseLeave}
        min={min}
        type={type}
        disabled={disabled}
      />
      {suffix}
    </>
  ))
  
