const OperatorMenu = memo((props) => {
  const {
    selectedOperator,
    operatorType,
    className,
    handleOperatorMenuClick,
    isFilterDisplayBar,
    propertyName,
    selectedAttribute = null, // can be null in some cases
    activityFilterProperty, // * CX-1876 
    isScreenProperty
  } = props
  const [visible, onVisibleChange] = useState(false)
  const [serverServedOperatorType, setServerServedOperatorType] = useState('')
  const { eventPropertyList } = useSelector(state => state.commonReducer)
  const dynamicOperatorType = serverServedOperatorType || operatorType
  const { viewOnly, disabledFilterMessage } = useAppliedFilterContext();
  let operatorOptions = dynamicOperatorType && operator[dynamicOperatorType]
  if (serverServedOperatorType === 'integer') {
    operatorOptions = operatorOptions.filter(({ attribute }) =>
      !['greater_or_equal', 'less_or_equal'].includes(attribute)
    );
  }

  if (isScreenProperty) {
    operatorOptions = operatorOptions.filter(({ attribute }) =>
      !['greater', 'less'].includes(attribute)
    );
  }
  // eslint-disable-next-line arrow-body-style
  operatorOptions = useMemo(() => {
    // @note: contains_any and not_contains_any are only allowed for session_screen_list and screen_name
    return (operatorOptions || []).filter(({ attribute }) => {
      if (['contains_any', 'not_contains_any'].includes(attribute) && !['session_screen_list', 'screen_name'].includes(selectedAttribute)) return false
      return true
    })
  }, [operatorOptions, selectedAttribute])
  const handleClick = useCallback((e) => {
    onVisibleChange(false)
    handleOperatorMenuClick(e, dynamicOperatorType, isScreenProperty)
  }, [onVisibleChange, handleOperatorMenuClick, dynamicOperatorType, isScreenProperty])

  useEffect(() => {
    if (propertyName) {
      const opIndx = findLastIndex(eventPropertyList, { propertyName });
      if (opIndx > -1) setServerServedOperatorType(eventPropertyList[opIndx]['propertyType']);
      else setServerServedOperatorType('');
    } else setServerServedOperatorType('');
  }, [propertyName]);

  const menus = useMemo(() => operatorOptions?.length && operatorOptions.map(
    ({ display, attribute, format, title }) =>
      display && (
        <MenuItem key={attribute} format={format}>
          {title}
        </MenuItem>
      )
  ), [operatorOptions]);
  const extraPrefix = useMemo(() => Boolean(isFilterDisplayBar && singleValueType.includes(dynamicOperatorType)) && <span>is </span>, [selectedOperator, isFilterDisplayBar, operatorType])
  const displayTitle = useMemo(() => Object.keys(mappedOperator).includes(selectedOperator?.attribute)
    ? mappedOperator[selectedOperator?.attribute]
    : selectedOperator?.attribute, [selectedOperator])
  return (
     <Tooltip title={disabledFilterMessage}>
      {extraPrefix}
      <Dropdown
        trigger={['click']}
        overlayClassName="increased-dropdown-zIndex select-operator-menu"
        overlay={
          <Menu
            onClick={handleClick}
            selectedKeys={[selectedOperator?.attribute]}
          >
            <MenuItemGroupWrapper
              title="Select filter operator"
              id="filter-operator"
            >
              {menus}
            </MenuItemGroupWrapper>
          </Menu>
        }
        visible={visible}
        onVisibleChange={onVisibleChange}
        disabled={viewOnly}
      >
       
        {isFilterDisplayBar ? (
          <FilterSpacing 
               id={activityFilterProperty ? activityFilterProperty.id : undefined}
                >
            <a href="#!" onClick={handleDefault} className={cs(viewOnly && 'filter-input-disabled')} >{
                selectedOperator?.title === 'select_activity' ?
                <StyledPropertyPlaceholder >
                    Select
                </StyledPropertyPlaceholder> : selectedOperator?.title
            }</a>
          </FilterSpacing>
        ) : (
          <Button className={className} onClick={handleDefault}>
            {displayTitle}
            {visible ? <UpOutlined /> : <DownOutlined />}
          </Button>
        )}
      </Dropdown>
      </Tooltip>
  )
})

const SelectAllAndClear = memo((props) => {
  const { 
    operatorAttribute, 
    isOperatorRadio,
    newFetchedList, 
    operatorType, 
    handleSelectAllOptions,
    disableSelect,
    handleClearAllOptions,
    disableClear,
  } = props;
  
  const ActionButton = styled(Button)`
    color: #5D97FF;
    padding: 0;
    border: none;
    font-size: 12px;
    font-weight: 400;
    font-family: inter, sans-serif;
    &:hover, &:active, &:disabled {
      background: none !important;
    }
  `;

  const ButtonWrapper = styled.div`
    display: flex;
    align-items: center;
  `

  const Divider = styled.span`
    width: 1px;
    height: 1rem;
    background-color: #CCCCCC;
    margin: 0 8px;
  `

  const validOperatorAttributes = ['contains', 'greater', 'less', 'not_contains'];
  const validOperatorTypes = ['date'];

  if (
    validOperatorAttributes.includes(operatorAttribute) ||
    validOperatorTypes.includes(operatorType) ||
    isOperatorRadio ||
    newFetchedList?.length <= 0
  ) return;
  
  return (
    <ButtonWrapper>
      <ActionButton size='small' onClick={handleSelectAllOptions} disabled={disableSelect}>Select all</ActionButton>
      <Divider />
      <ActionButton size='small' onClick={handleClearAllOptions} disabled={disableClear}>Clear all</ActionButton>
    </ButtonWrapper>
  );
})

