function bringSelectedItemsToTop(arr1, arr2, attribute) {
  if (!arr1) return arr1;
  if (isObject(arr1[0])) {
    const presentItems = filter(arr1, (obj) =>
      includes(arr2, obj[attribute] ?? obj.uxcamuserid)
    );
    const remainingItems = difference(arr1, presentItems);
    const sortedArray = sortBy(presentItems.concat(remainingItems), (obj) =>
      includes(arr2, obj[attribute] ?? obj.uxcamuserid) ? 0 : 1
    );
    return sortedArray;
  }

  const presentItems = intersection(arr1, arr2);
  const remainingItems = difference(arr1, presentItems);
  const result = concat(presentItems, remainingItems);
  return result;
}

function bringMissingItemsToTop(arr1, arr2, attributeName) {
  if (!arr1) return arr1;

  const isObjectList = isObject(arr1[0]);
  if (!isObjectList) {
    const missingItems = difference(arr2, arr1);
    return union(missingItems, arr1);
  }
  // * if object and following attributes then only process
  const handlesUxcamUserId = attributeName === 'uxcam_user_id';
  const handlesUxcamUserIdName = attributeName === 'uxcamuserid';
  if (!handlesUxcamUserId && !handlesUxcamUserIdName) return arr1;

  const getKey = (obj) => obj?.uxcamuserid ?? obj?.id ?? obj?.name;
  const existingKeys = arr1.map(getKey).filter(Boolean);
  const missingItems = (arr2 || []).filter((val) => !existingKeys.includes(val));
  if (!missingItems.length) return arr1;

  const createMissingObject = (val) => (
    handlesUxcamUserId
      ? { uxcamuserid: val, hasCustomUserId: true }
      : { uxcamuserid: val, name: val }
  );

  return union(missingItems.map(createMissingObject), arr1);
}

